mapper.select:
SELECT a.activity_id, a.activity_name, a.status, a.tool_type, a.threshold_amount, a.discount_amount, a.discount_rate, a.max_discount, a.coupon_template_id, a.region_code, s.product_id, s.sku_id, s.scope_type FROM t_activity a INNER JOIN t_activity_scope s ON a.activity_id = s.activity_id AND a.region_code = s.region_code WHERE a.is_deleted = 0 AND s.is_deleted = 0 AND a.region_code = #{regionCode}
AND s.scope_type = #{scopeType}
AND ( (s.product_id = #{productId} AND s.sku_id = #{skuId}) OR ( s.product_id = #{productId} AND (s.sku_id IS NULL OR s.sku_id = '') AND NOT EXISTS ( SELECT 1 FROM t_activity sku_activity INNER JOIN t_activity_scope sku_scope ON sku_activity.activity_id = sku_scope.activity_id AND sku_activity.region_code = sku_scope.region_code WHERE sku_activity.is_deleted = 0 AND sku_scope.is_deleted = 0 AND sku_activity.region_code = #{regionCode} AND sku_activity.activity_id = a.activity_id
AND sku_scope.scope_type = #{scopeType}
AND sku_scope.product_id = #{productId} AND sku_scope.sku_id = #{skuId} ) ) )
AND s.product_id = #{productId} AND (s.sku_id IS NULL OR s.sku_id = '')
ORDER BY CASE a.status WHEN 'ONLINE' THEN 1 WHEN 'APPROVED' THEN 2 WHEN 'PAUSED' THEN 3 WHEN 'PENDING_APPROVAL' THEN 4 WHEN 'DRAFT' THEN 5 ELSE 6 END, a.updated_at DESC, a.activity_id ASC
